## 6️⃣ Sample refactored `app.js` (all suggestions combined)

```js
/* -------------------------------------------------
   app.js – Refactored with security & error handling
   ------------------------------------------------- */
require('dotenv').config(); // <-- ensure .env is NOT in version control

const express   = require('express');
const helmet    = require('helmet');
const cors      = require('cors');
const rateLimit = require('express-rate-limit');

const app = express();

/* ---------- Basic hardening ---------- */
app.disable('x-powered-by');
app.set('trust proxy', 1); // set to 0 if you run directly (no proxy)

// Helmet for secure headers
app.use(helmet());

// CORS – whitelist via env, fallback to none (fails closed)
app.use(
  cors({
    origin: process.env.ALLOWED_ORIGINS?.split(',') || [],
    credentials: true,
  })
);

// Rate limiting – adjust limits as needed
app.use(
  rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 100,
    standardHeaders: true,
    legacyHeaders: false,
  })
);

// Body parser with payload size guard
app.use(express.json({ limit: '10kb' }));

/* ---------- Utility: async wrapper ---------- */
const asyncWrap = fn => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

/* ---------- Routes ---------- */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get(
  '/users',
  asyncWrap(async (req, res) => {
    // Future validation can happen here
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob',   email: 'bob@example.com' },
    ]);
  })
);

/* ---------- Central error handler ---------- */
app.use((err, req, res, next) => {
  // Log – replace with a structured logger for production
  console.error(`[${new Date().toISOString()}] ${err.stack || err}`);

  const isProd = process.env.NODE_ENV === 'production';
  const status = err.statusCode || 500;
  const message = isProd ? 'Internal Server Error' : err.message;

  res.status(status).json({ error: message });
});

/* ---------- Server bootstrap ---------- */
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

/* ---------- Process‑level safety ---------- */
process.on('unhandledRejection', err => {
  console.error('Unhandled promise rejection:', err);
  process.exit(1);
});
process.on('uncaughtException', err => {
  console.error('Uncaught exception:', err);
  process.exit(1);
});
function gracefulShutdown() {
  console.log('Received kill signal – shutting down');
  server.close(() => process.exit(0));
}
process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

module.exports = app; // for integration tests
```

