#!/usr/bin/env node
/**
 * verify-creds.js
 *
 * Quick sanity‑check for the credentials that live in .env.test.
 * Run it locally (e.g. `node verify-creds.js`) after you have `npm install`ed
 * the required dependencies.
 *
 * NOTE:
 *   • The script never logs the raw secret values.
 *   • All requests use short time‑outs so a hanging service won’t block the script.
 *   • Errors are caught and displayed in a concise way – you can expand the
 *     handling if you need more debug info.
 */

require('dotenv').config({ path: '.env.test' }); // load the test file (remove in prod)

const { Client } = require('pg');
const fetch = require('node-fetch'); // node >=18 has native fetch, otherwise install node-fetch

// -------------------------------------------------------------------
// 1️⃣  PostgreSQL connectivity test
// -------------------------------------------------------------------
async function testDatabase() {
  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl) {
    console.warn('❗ DATABASE_URL not set – skipping DB test');
    return;
  }

  const client = new Client({ connectionString: dbUrl, connectionTimeoutMillis: 5000 });
  try {
    await client.connect();
    const res = await client.query('SELECT NOW() AS now');
    console.log('✅ PostgreSQL connection succeeded – server time:', res.rows[0].now);
  } catch (err) {
    console.error('❌ PostgreSQL connection failed:', err.message);
  } finally {
    await client.end().catch(() => {}); // ignore errors on close
  }
}

// -------------------------------------------------------------------
// 2️⃣  API‑key validation helpers
// -------------------------------------------------------------------
async function ping(url, headers = {}, name) {
  try {
    const res = await fetch(url, {
      method: 'GET',
      headers,
      timeout: 5000, // ms – works in node-fetch; native fetch uses AbortController
    });
    if (!res.ok) {
      console.error(`❌ ${name} responded with ${res.status} ${res.statusText}`);
      return;
    }
    console.log(`✅ ${name} responded OK`);
  } catch (err) {
    console.error(`❌ ${name} request failed:`, err.message);
  }
}

// -------------------------------------------------------------------
// 3️⃣  Individual service checks
// -------------------------------------------------------------------
async function testAnthropic() {
  const key = process.env.ANTHROPIC_API_KEY;
  if (!key) {
    console.warn('❗ ANTHROPIC_API_KEY not set – skipping');
    return;
  }
  // Anthropic provides a simple “metadata” endpoint we can safely hit
  await ping(
    'https://api.anthropic.com/v1/metadata',
    { 'x-api-key': key, 'anthropic-version': '2023-06-01' },
    'Anthropic API'
  );
}

async function testStripe() {
  const key = process.env.STRIPE_SECRET_KEY;
  if (!key) {
    console.warn('❗ STRIPE_SECRET_KEY not set – skipping');
    return;
  }
  // A cheap request: retrieve the account (or do a health‑check endpoint)
  await ping(
    'https://api.stripe.com/v1/account',
    { Authorization: `Bearer ${key}` },
    'Stripe API'
  );
}

async function testLogfire() {
  const token = process.env.LOGFIRE_TOKEN;
  if (!token) {
    console.warn('❗ LOGFIRE_TOKEN not set – skipping');
    return;
  }
  // Logfire offers a minimal “ping” endpoint (replace with the proper one if needed)
  await ping(
    'https://api.logfire.io/v1/ping',
    { Authorization: `Bearer ${token}` },
    'Logfire API'
  );
}

// -------------------------------------------------------------------
// 4️⃣  Run all checks
// -------------------------------------------------------------------
(async () => {
  console.log('🔎 Starting credential verification…\n');

  await testDatabase();
  await testAnthropic();
  await testStripe();
  await testLogfire();

  console.log('\n🛑 Done.');
})();
```

