```js
// -----------------------------------------------------
// app.js – Hardened Express server (security & error handling)
// -----------------------------------------------------

require('dotenv').config();               // Loads .env (port, NODE_ENV, etc.)
const express = require('express');
const helmet = require('helmet');         // Secure HTTP headers
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');         // Structured request logging
const { validationResult, query } = require('express-validator'); // Example validator
const createError = require('http-errors'); // For consistent error objects

const app = express();

// -----------------------------------------------------
// 1️⃣ Middleware – security, parsing, logging
// -----------------------------------------------------
app.use(helmet());                         // X‑XSS‑Protection, CSP, etc.
app.use(express.json());                  // Parse JSON bodies
app.use(express.urlencoded({ extended: false }));

// CORS – adjust `origin` to your front‑end domain(s)
app.use(cors({
  origin: process.env.CORS_ORIGIN || '*', // replace '*' with a whitelist in prod
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
}));

// Rate limiting – 100 requests per 15 min per IP (tune to your use‑case)
app.use(
  rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 100,
    standardHeaders: true,
    legacyHeaders: false,
    message: {
      status: 429,
      error: 'Too many requests, please try again later.'
    }
  })
);

// Request logging (skip in test env)
if (process.env.NODE_ENV !== 'test') {
  app.use(morgan('combined'));
}

// -----------------------------------------------------
// 2️⃣ Routes
// -----------------------------------------------------

// Health check – never throws, just returns status
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * In a real app this would query a DB; here we keep the static array.
 * Example of input validation: you could allow a `?limit=` query param.
 */
app.get(
  '/users',
  // ---- optional validation example (limit must be an integer 1‑100) ----
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .toInt()
    .withMessage('limit must be an integer between 1 and 100'),
  // --------------------------------------------------------------------
  (req, res, next) => {
    // Handle validation errors early
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      // `createError` helps produce consistent http-errors
      return next(createError(400, { validation: errors.array() }));
    }

    const staticUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Example of using a query param safely (no injection risk)
    const limit = req.query.limit;
    const result = limit ? staticUsers.slice(0, limit) : staticUsers;

    res.json(result);
  }
);

// -----------------------------------------------------
// 3️⃣ Centralised error handling
// -----------------------------------------------------
app.use((err, req, res, next) => {
  // If the error is an http-errors object, its status is already set
  const status = err.status || 500;

  // In production we don’t leak stack traces
  const response = {
    status,
    error: err.message || 'Internal Server Error',
  };

  // Optionally add a debug field when not in prod
  if (process.env.NODE_ENV !== 'production' && err.stack) {
    response.stack = err.stack;
  }

  // Log the error (you could replace with a logger like Winston/Bunyan)
  console.error(`[${new Date().toISOString()}]`, err);

  res.status(status).json(response);
});

// -----------------------------------------------------
// 4️⃣ Server start (graceful shutdown)
// -----------------------------------------------------
if (require.main === module) {
  const PORT = process.env.PORT || 3000;

  const server = app.listen(PORT, () => {
    console.info(`🚀 Server listening on http://localhost:${PORT}`);
  });

  // Graceful shutdown on SIGTERM / SIGINT
  const signals = ['SIGINT', 'SIGTERM'];
  signals.forEach(sig => {
    process.on(sig, () => {
