#!/usr/bin/env node
/* --------------------------------------------------------------
   verify-credentials.js
   Quick sanity‑check that the credentials in your .env.* files
   can reach their respective services.

   Usage:
     $ npm i pg node-fetch@2   # install deps (fetch v2 works in Node <18)
     $ node verify-credentials.js   # reads from process.env
   -------------------------------------------------------------- */

require('dotenv').config({ path: '.env.test' }); // <-- adjust path if needed

const { Client } = require('pg');
const fetch = require('node-fetch');

// ------------------------------------------------------------------
// 1️⃣  Check PostgreSQL connectivity
// ------------------------------------------------------------------
async function checkDatabase() {
  const url = process.env.DATABASE_URL;
  if (!url) {
    console.warn('⚠️  DATABASE_URL not defined.');
    return;
  }

  const client = new Client({ connectionString: url });

  try {
    await client.connect();
    // A cheap, safe query that requires no privileges
    const res = await client.query('SELECT 1 AS ok;');
    if (res.rows[0]?.ok === 1) {
      console.log('✅  PostgreSQL connection succeeded.');
    } else {
      console.warn('⚠️  PostgreSQL responded, but unexpected result.');
    }
  } catch (err) {
    console.error('❌  PostgreSQL connection FAILED:', err.message);
  } finally {
    await client.end().catch(() => {});
  }
}

// ------------------------------------------------------------------
// 2️⃣  Helper to test a generic HTTP API key header
// ------------------------------------------------------------------
async function testHttpEndpoint({ name, url, keyHeader, key }) {
  if (!key) {
    console.warn(`⚠️  ${name} key not defined.`);
    return;
  }

  try {
    const response = await fetch(url, {
      method: 'GET',
      headers: { [keyHeader]: key },
    });

    if (response.ok) {
      console.log(`✅  ${name} responded with ${response.status}.`);
    } else {
      console.warn(
        `⚠️  ${name} responded with ${response.status} (${response.statusText}).`
      );
    }
  } catch (err) {
    console.error(`❌  ${name} request FAILED:`, err.message);
  }
}

// ------------------------------------------------------------------
// 3️⃣  Test external services
// ------------------------------------------------------------------
async function checkExternalServices() {
  // ── Anthropic (text generation) ────────────────────────
  await testHttpEndpoint({
    name: 'Anthropic',
    url: 'https://api.anthropic.com/v1/health', // generic health endpoint
    keyHeader: 'x-api-key',
    key: process.env.ANTHROPIC_API_KEY,
  });

  // ── Stripe (secret key) ─────────────────────────────────
  await testHttpEndpoint({
    name: 'Stripe',
    url: 'https://api.stripe.com/v1/charges?limit=1',
    keyHeader: 'Authorization',
    key: `Bearer ${process.env.STRIPE_SECRET_KEY}`,
  });

  // ── Logfire (token) ─────────────────────────────────────
  await testHttpEndpoint({
    name: 'Logfire',
    url: 'https://api.logfire.io/v1/health',
    keyHeader: 'Authorization',
    key: `Bearer ${process.env.LOGFIRE_TOKEN}`,
  });
}

// ------------------------------------------------------------------
// 4️⃣  Main entry point
// ------------------------------------------------------------------
(async () => {
  console.log('🔎 Starting credential verification...\n');

  await checkDatabase();
  console.log(''); // blank line for readability
  await checkExternalServices();

  console.log('\n✅  Verification finished.');
})();
```

### How it works

| Step | What it does | Why it’s safe |
|------|--------------|---------------|
| **Load .env.test** | `dotenv` reads the file into `process.env`. | Secrets stay in memory only; nothing is written to disk. |
| **PostgreSQL check** | Opens a short‑lived connection, runs `SELECT 1`. | No data is mutated; the query is universally permitted. |
| **HTTP checks** | Sends a single **GET** request with the appropriate auth header to a *public health/heartbeat* endpoint (or a cheap read‑only endpoint). | We never send sensitive payloads, only a header that the service expects for authentication. |
| **Result logging** | Prints ✅/⚠️/❌ with a brief description. | The actual key values are **never printed**. Only the presence/absence and HTTP status are shown. |

