// app.js
// Production‑ready skeleton with security best practices

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const pino = require('pino');
const logger = pino(); // replace with winston if you prefer

const app = express();

/* -------------------------------------------------
   Middleware
---------------------------------------------------*/

// Secure HTTP headers
app.use(helmet());

// Enable CORS (adjust origin as needed)
app.use(cors({
  origin: process.env.CORS_ORIGIN || '*', // tighten in production
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// Rate limiting – mitigate brute‑force / DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                 // limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Body parsing (JSON & URL‑encoded)
// Even if you currently only have GET routes, having this in place
// prevents later accidental trust of raw request bodies.
app.use(express.json());
app.use(express.urlencoded({ extended: false }));

// Request logger (simple)
app.use((req, res, next) => {
  logger.info({ method: req.method, url: req.originalUrl, ip: req.ip });
  next();
});

/* -------------------------------------------------
   Routes
---------------------------------------------------*/

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res, next) => {
  try {
    // In a real app this would come from a DB; we keep the static list for demo.
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];
    res.json(users);
  } catch (err) {
    // Forward any unexpected error to the global error handler
    next(err);
  }
});

/* -------------------------------------------------
   404 handler
---------------------------------------------------*/
app.use((req, res, next) => {
  res.status(404).json({ error: 'Not Found' });
});

/* -------------------------------------------------
   Global error handler
---------------------------------------------------*/
app.use((err, req, res, next) => {
  // Log the full error for internal debugging
  logger.error({ err, url: req.originalUrl, method: req.method });

  // Do not expose stack traces in production
  const isProd = process.env.NODE_ENV === 'production';
  const status = err.status || 500;
  const message = isProd ? 'Internal Server Error' : err.message;

  res.status(status).json({ error: message });
});

/* -------------------------------------------------
   Server start (with graceful shutdown)
---------------------------------------------------*/
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
});

/* Graceful shutdown */
function shutdown() {
  logger.info('Graceful shutdown initiated...');
  server.close(() => {
    logger.info('HTTP server closed.');
    // If you have DB connections, close them here.
    process.exit(0);
  });

  // Force exit after 10 seconds
  setTimeout(() => {
    logger.warn('Forcefully terminating after timeout.');
    process.exit(1);
  }, 10_000);
}

process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

module.exports = app; // Export for testing
```

### What changed?

| Change | Security / Robustness Benefit |
|--------|------------------------------|
| `helmet()` | Sets dozens of security‑related headers (CSP, X‑Content‑Type‑Options, HSTS, etc.). |
| `cors()` | Explicitly defines who may call the API, reducing risk of cross‑origin data leakage. |
| `express-rate-limit` | Throttles abusive IPs, mitigating DoS and credential‑stuffing attacks. |
| Centralized **error‑handling** middleware | Guarantees a unified JSON error format and hides internal stack traces from clients. |
| 404 handler | Prevents “fall‑through” exposures of server internals. |
| Structured logging (`pino`) | Provides audit trails, easier debugging, and can be piped to log aggregators. |
| Graceful shutdown | Avoids abrupt termination that could corrupt in‑flight DB writes or open sockets. |
| `express.json()` & `express.urlencoded()` | Normalises request bodies, preventing malicious payloads from bypassing validation later. |
| `process.env.PORT` & `process.env.NODE_ENV` | Encourages configuration via environment variables, a best practice for twelve‑factor apps. |

---

## 3. Input Validation (Future‑Proofing)

Even though the current routes take no user‑supplied data, you’ll likely add POST/PUT endpoints. Here’s a quick checklist for each new endpoint:

| Validation Layer | Library / Technique | Example |
|------------------|---------------------|---------|
| **Schema validation** | `joi`, `zod`, or `express-validator` | `const schema = Joi.object({ email: Joi.string().email().required() });` |
| **Sanitisation** | `express-validator` sanitizers, `xss-clean` | `req.body.email = sanitizer.sanitize(req.body.email);` |
| **Parameter whitelisting** | Only accept known query / path params. | `app.get('/users/:id', (req,res)=>{ const id = parseInt(req.params.id,10); if(isNaN(id)) return res.status(400).json({error:'Invalid id'}); …});` |
| **Rate‑limit per endpoint** | Apply a stricter limiter on auth routes. | `app.use('/login', loginLimiter, loginHandler);` |
| **CSRF protection** (if you serve browsers) | `csurf` middleware for state‑changing routes. | `app.use(csrf({ cookie: true }));` |

