 * (The original app returned a static array; keep that for now, but
 *  the pattern below shows how to safely accept input.)
 */
app.get(
  '/users/:id',
  [
    // ---- Input validation (express‑validator) ----
    param('id')
      .trim()
      .isInt({ gt: 0 }).withMessage('User ID must be a positive integer')
      .toInt(),
  ],
  asyncHandler(async (req, res) => {
    // ---- Validation result handling ----
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const userId = req.params.id;
    // In a real app you’d fetch from DB – here we keep the static example:
    const staticUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];
    const user = staticUsers.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }
    res.json(user);
  })
);

app.get(
  '/users',
  asyncHandler(async (req, res) => {
    // No input, but we still wrap it for consistent error handling
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  })
);

// ---------- 4️⃣ 404 handler ----------
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// ---------- 5️⃣ Central error handler ----------
app.use((err, req, res, next) => {
  // Log the error – in production you’d probably forward to a logging service
  console.error(err);

  // Do not leak internal details; send a generic message.
  const status = err.status || 500;
  const message = status === 500 ? 'Internal server error' : err.message;

  res.status(status).json({ error: message });
});

// ---------- 6️⃣ Server start ----------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

> **What changed?**  
> * All routes are wrapped in `asyncHandler`, so any thrown error automatically reaches the central error middleware.  
> * Input validation is demonstrated on the `/users/:id` endpoint using **express‑validator**; you can extend this pattern to POST/PUT bodies with `body('field')`.  
> * The app now **protects headers**, **limits request size**, **logs every request**, **enforces rate limiting**, and **rejects unknown origins**.  
> * A **generic 404** and **error‑handling** middleware guarantee that the server never returns stack traces or unstructured errors to a client.  
> * Configuration (port, CORS whitelist) is read from environment variables via `dotenv`, keeping secrets out of source control.

