     max: 100,
   });
   app.use(limiter);
   ```

3. **Add a generic error handler** (add at the very end, before `app.listen`)

   ```js
   // 404
   app.use((req, res) => res.status(404).json({ error: 'Not found' }));

   // error handler
   app.use((err, req, res, next) => {
     console.error(err);
