  const secret = process.env.STRIPE_SECRET_KEY;
  if (!secret) return fail('Stripe secret key', new Error('missing STRIPE_SECRET_KEY'));

  const stripe = Stripe(secret);

  try {
    await stripe.balance.retrieve();
    ok('Stripe secret key');
  } catch (e) {
    // Stripe throws an error with `type: 'StripeAuthenticationError'` for bad keys
    if (e?.type === 'StripeAuthenticationError')
      fail('Stripe secret key', new Error('unauthorized'));
    else
      fail('Stripe API call', e);
  }
}

