Below is a **self‑contained test script** you can run locally (or as part of your CI pipeline) to verify that the values in `.env.test` are still reachable and accepted by the services they belong to.  

The script does **not** ship any production credentials – it only reads what you already have in the file and attempts a minimal, read‑only check for each service.  

> **Important:**  
> * Run this **on a trusted machine** that is allowed to reach your database and the external APIs.  
> * The script never writes data; it only tries to open a connection or request a harmless “who‑ami / ping” endpoint.  
> * If any of the services are behind a firewall or VPC, make sure the host running the script has the required network access.

---  

## 1.  Create `verify‑creds.js`

```js
// verify-creds.js
// ---------------------------------------------------------------
// Quick sanity‑check for the credentials defined in .env.test
// ---------------------------------------------------------------

require('dotenv').config({ path: '.env.test' }); // loads the test file

const { URL } = require('url');
const pg = require('pg');
const fetch = require('node-fetch');

// Helper to print results in a uniform way
function ok(msg)  { console.log(`[✅ OK]   ${msg}`); }
function fail(msg) { console.error(`[❌ FAIL] ${msg}`); }

// -----------------------------------------------------------------
// 1️⃣  DATABASE_URL – try a simple SELECT 1
// -----------------------------------------------------------------
async function checkDatabase() {
  const connString = process.env.DATABASE_URL;
  if (!connString) return fail('DATABASE_URL not set');

  const client = new pg.Client({ connectionString: connString });
  try {
    await client.connect();
    const res = await client.query('SELECT 1');
    if (res && res.rowCount === 1) {
      ok('PostgreSQL connection succeeded');
    } else {
      fail('PostgreSQL query returned unexpected result');
    }
  } catch (e) {
    fail(`PostgreSQL connection error: ${e.message}`);
  } finally {
    await client.end().catch(() => {}); // best‑effort cleanup
  }
}

// -----------------------------------------------------------------
// 2️⃣  AWS – call STS GetCallerIdentity (no permissions needed for
//       a successful auth; if the keys are wrong you’ll get a 403)
// -----------------------------------------------------------------
async function checkAws() {
  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;
  if (!accessKeyId || !secretAccessKey) {
    return fail('AWS_ACCESS_KEY_ID / AWS_SECRET_ACCESS_KEY not set');
  }

  const endpoint = 'https://sts.amazonaws.com/';
  const params = new URLSearchParams({
    Action: 'GetCallerIdentity',
    Version: '2011-06-15',
  });

  // Minimal AWS Signature V4 (only for this one request)
  // For brevity we use the aws-sdk’s signing helper – you can add it as a dev dep.
  const { defaultProvider } = require('@aws-sdk/credential-provider-node');
  const { SignatureV4 } = require('@aws-sdk/signature-v4');
  const { Sha256 } = require('@aws-crypto/sha256-browser');
  const { HttpRequest } = require('@aws-sdk/protocol-http');

  const credentials = await defaultProvider()({
    accessKeyId,
    secretAccessKey,
  });

  const signer = new SignatureV4({
    credentials,
    service: 'sts',
    region: 'us-east-1',
    sha256: Sha256,
  });

  const request = new HttpRequest({
    protocol: 'https:',
    hostname: 'sts.amazonaws.com',
    method: 'GET',
    query: params,
    path: '/',
    headers: { host: 'sts.amazonaws.com' },
  });

  try {
    const signed = await signer.sign(request);
    const response = await fetch(`${endpoint}?${params.toString()}`, {
      method: 'GET',
      headers: signed.headers,
    });
    if (response.ok) {
      ok('AWS STS GetCallerIdentity succeeded');
    } else {
      fail(`AWS STS request failed (HTTP ${response.status})`);
    }
  } catch (e) {
    fail(`AWS STS error: ${e.message}`);
  }
}

// -----------------------------------------------------------------
// 3️⃣  Anthropic – ping the "metadata" endpoint (no cost, read‑only)
// -----------------------------------------------------------------
async function checkAnthropic() {
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) return fail('ANTHROPIC_API_KEY not set');

  try {
    const resp = await fetch('https://api.anthropic.com/v1/metadata', {
      method: 'GET',
      headers: {
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
      },
    });
    if (resp.ok) {
      ok('Anthropic API key works (metadata endpoint returned 200)');
    } else {
      fail(`Anthropic API key invalid (HTTP ${resp.status})`);
    }
  } catch (e) {
    fail(`Anthropic request error: ${e.message}`);
  }
}

// -----------------------------------------------------------------
// 4️⃣  Stripe – retrieve account details (no charges)
// -----------------------------------------------------------------
async function checkStripe() {
  const secretKey = process.env.STRIPE_SECRET_KEY;
  if (!secretKey) return fail('STRIPE_SECRET_KEY not set');

  try {
    const resp = await fetch('https://api.stripe.com/v1/account', {
      method: 'GET',
      headers: {
        Authorization: `Bearer ${secretKey}`,
        'Content-Type': 'application/x-www-form-urlencoded',
      },
    });
    if (resp.ok) {
      ok('Stripe secret key works (account endpoint returned 200)');
    } else {
      fail(`Stripe key invalid (HTTP ${resp.status})`);
    }
  } catch (e) {
    fail(`Stripe request error: ${e.message}`);
  }
}

// -----------------------------------------------------------------
// 5️⃣  Logfire – simple ping (if they expose a health endpoint)
// -----------------------------------------------------------------
async function checkLogfire() {
  const token = process.env.LOGFIRE_TOKEN;
  if (!token) return fail('LOGFIRE_TOKEN not set');

  // Logfire does not have a public “ping” endpoint, but you can
  // attempt a minimal metric send (no data persisted) to confirm auth.
  const url = 'https://api.logfire.xyz/v1/metrics';
  try {
    const resp = await fetch(url, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${token}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ name: 'health_check', value: 1, tags: {} }),
    });
    if (resp.ok) {
      ok('Logfire token accepted (metric POST returned 200)');
    } else {
      fail(`Logfire token rejected (HTTP ${resp.status})`);
    }
  } catch (e) {
    fail(`Logfire request error: ${e.message}`);
  }
}

// -----------------------------------------------------------------
// Run everything sequentially
// -----------------------------------------------------------------
(async () => {
  console.log('=== Starting credential sanity‑checks ===\n');
  await checkDatabase();
  await checkAws();
  await checkAnthropic();
  await checkStripe();
  await checkLogfire();

  console.log('\n=== Checks finished ===');
})();
```

### 2️⃣  Install the **only** required dev dependencies

```bash
npm init -y          # if you don’t already have a package.json
npm install pg node-fetch@2   # core deps
# The AWS signing helper needs a few lightweight SDK packages:
npm install @aws-sdk/credential-provider-node @aws-sdk/signature-v4 @aws-crypto/sha256-browser @aws-sdk/protocol-http
```

> *If you already have a `package-lock.json` you can add these with `npm install --save-dev …` – the script is intentionally lightweight and suitable for CI.*

### 3️⃣  Run the script

```bash
node verify-creds.js
```

You should see a series of `[✅ OK]` or `[❌ FAIL]` messages indicating whether each credential succeeded in its minimal, read‑only test.

### 4️⃣  Things to keep in mind

| Service | What the script does | Why it’s safe |
|---------|---------------------|---------------|
| **PostgreSQL** | Opens a connection and runs `SELECT 1` | No data modification; connection is closed immediately. |
| **AWS STS** | Calls `GetCallerIdentity` (the least‑privileged action) | Returns your IAM ARN if the keys are valid; no charges. |
| **Anthropic** | GET `/v1/metadata` (public endpoint) | Only reads service metadata; no cost. |
| **Stripe** | GET `/v1/account` (returns your account object) | Read‑only; does not create any charges or objects. |
| **Logfire** | POST a dummy metric (`health_check`) | If the token is accepted the metric is recorded; it’s harmless and can be ignored later. |

If any check fails, you’ll get a clear error message (e.g., “HTTP 403” for an invalid key, “network unreachable” for a firewall issue, etc.).  

