#!/usr/bin/env node
/**
 * Simple credential‑verification script.
 *
 * - Connects to the Postgres DB given by DATABASE_URL.
 * - Calls a lightweight AWS STS GetCallerIdentity (requires AWS keys).
 * - Pings the Anthropic “completions” endpoint with a tiny request.
 * - Calls Stripe's “retrieve account” endpoint.
 * - Makes a GET request to Logfire's health endpoint (if a token is provided).
 *
 * All requests have short time‑outs and never log the secret values.
 * The script exits with code 0 if *all* checks succeed, otherwise 1.
 */

require('dotenv').config({ path: '.env.test' }); // adjust if you use a different file
const { URL } = require('url');
const pg = require('pg');
const https = require('https');
const { STSClient, GetCallerIdentityCommand } = require('@aws-sdk/client-sts');
const fetch = require('node-fetch'); // node >=18 has native fetch, but keep compatibility
const Stripe = require('stripe');

const TIMEOUT_MS = 5000;

/* -------------------------------------------------
   Helper utilities
   ------------------------------------------------- */
function withTimeout(promise) {
  return Promise.race([
    promise,
    new Promise((_, reject) =>
      setTimeout(() => reject(new Error('Timed out')), TIMEOUT_MS)
    ),
  ]);
}

function logResult(name, ok, details = '') {
  const status = ok ? '✅' : '❌';
  console.log(`${status} ${name}${details ? ': ' + details : ''}`);
}

/* -------------------------------------------------
   1️⃣ PostgreSQL connectivity test
   ------------------------------------------------- */
async function testPostgres() {
  const connStr = process.env.DATABASE_URL;
  if (!connStr) throw new Error('DATABASE_URL not set');

  const client = new pg.Client({ connectionString: connStr, ssl: { rejectUnauthorized: false } });
  await withTimeout(client.connect());
  // Run a cheap query that does not require any tables
  const res = await withTimeout(client.query('SELECT 1 AS ok'));
  await client.end();
  if (res.rows[0].ok !== 1) throw new Error('Unexpected query result');
}

/* -------------------------------------------------
   2️⃣ AWS STS GetCallerIdentity (checks key+secret)
   ------------------------------------------------- */
async function testAWS() {
  const { AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY } = process.env;
  if (!AWS_ACCESS_KEY_ID || !AWS_SECRET_ACCESS_KEY) {
    throw new Error('AWS credentials missing');
  }

  const sts = new STSClient({
    credentials: {
      accessKeyId: AWS_ACCESS_KEY_ID,
      secretAccessKey: AWS_SECRET_ACCESS_KEY,
    },
    region: 'us-east-1',
  });

  const cmd = new GetCallerIdentityCommand({});
  const data = await withTimeout(sts.send(cmd));
  if (!data?.Arn) throw new Error('No ARN returned');
}

/* -------------------------------------------------
   3️⃣ Anthropic API key check (lightweight request)
   ------------------------------------------------- */
async function testAnthropic() {
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) throw new Error('ANTHROPIC_API_KEY not set');

  const url = 'https://api.anthropic.com/v1/complete';
  const payload = {
    model: 'claude-3-haiku-20240307',   // any model that exists
    max_tokens: 1,
    prompt: '',
  };

  const resp = await withTimeout(
    fetch(url, {
      method: 'POST',
      headers: {
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json',
      },
      body: JSON.stringify(payload),
    })
  );

  if (resp.status === 401) throw new Error('Unauthorized (bad API key)');
  // 200/400 are both “valid” responses – we just needed the request to go through.
}

/* -------------------------------------------------
   4️⃣ Stripe secret key verification
   ------------------------------------------------- */
async function testStripe() {
  const key = process.env.STRIPE_SECRET_KEY;
  if (!key) throw new Error('STRIPE_SECRET_KEY not set');

  const stripe = Stripe(key, { apiVersion: '2023-10-16' });
  // `stripe.accounts.retrieve` works with both test and live keys without needing an account ID
  await withTimeout(stripe.accounts.retrieve());
}

/* -------------------------------------------------
   5️⃣ Logfire token ping (optional)
   ------------------------------------------------- */
async function testLogfire() {
  const token = process.env.LOGFIRE_TOKEN;
  if (!token) {
    console.log('⚠️ LOGFIRE_TOKEN not set – skipping Logfire check');
    return;
  }

  const url = `https://logfire.io/api/v1/ping`; // hypothetical endpoint; replace if needed
  const resp = await withTimeout(
    fetch(url, {
      headers: { Authorization: `Bearer ${token}` },
    })
  );

  if (!resp.ok) throw new Error(`Logfire ping failed: ${resp.status}`);
}

/* -------------------------------------------------
   Main runner
   ------------------------------------------------- */
(async () => {
  let allOk = true;

  try {
    await testPostgres();
    logResult('PostgreSQL connection', true);
  } catch (e) {
    allOk = false;
    logResult('PostgreSQL connection', false, e.message);
  }

  try {
    await testAWS();
    logResult('AWS STS credentials', true);
  } catch (e) {
    allOk = false;
    logResult('AWS STS credentials', false, e.message);
  }

  try {
    await testAnthropic();
    logResult('Anthropic API key', true);
  } catch (e) {
    allOk = false;
    logResult('Anthropic API key', false, e.message);
  }

  try {
    await testStripe();
    logResult('Stripe secret key', true);
  } catch (e) {
    allOk = false;
    logResult('Stripe secret key', false, e.message);
  }

  try {
    await testLogfire();
    logResult('Logfire token', true);
  } catch (e) {
    allOk = false;
    logResult('Logfire token', false, e.message);
  }

  process.exit(allOk ? 0 : 1);
})();
```

