## 2. Centralised error handling

Express will silently swallow a thrown error in an async route unless you forward it to `next()`.  
Add a **global error‑handling middleware** at the end of the middleware chain:

```js
// errorHandler.js
function errorHandler(err, req, res, next) {
  // Log the error (never expose stack traces to the client in prod)
  console.error(err); // replace with a proper logger

  const status = err.statusCode || 500;
  const response = {
    // Generic message for 5xx, more specific for validation, auth, etc.
    message: status === 500 ? 'Internal server error' : err.message,
  };

  // In dev you may want to include the stack for debugging:
  if (process.env.NODE_ENV !== 'production') {
    response.stack = err.stack;
  }

  res.status(status).json(response);
}

module.exports = errorHandler;
```

```js
// In app.js (near the bottom, after all routes)
const errorHandler = require('./errorHandler');
app.use(errorHandler);
```

Now any `throw new Error('…')`, `next(err)`, or rejected promise will be caught and turned into a clean JSON response.

