/* -----------------------------  Imports  ----------------------------- */
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');          // request logger
const { validateUserQuery } = require('./validators/users');
const errorHandler = require('./errorHandler');

/* --------------------------  Configuration  ------------------------ */
const app = express();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

/* ---------------------------  Middleware  -------------------------- */
app.use(helmet());                                 // Secure HTTP headers
app.use(cors({                                   // Adjust origins as needed
  origin: process.env.CORS_ORIGIN || '*',
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
}));
// Rate limiting: max 100 requests per 15‑minute window per IP
app.use(rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
}));
app.use(express.json({ limit: '1mb' }));          // Body parser + size limit
app.use(express.urlencoded({ extended: false })); // URL‑encoded parser
app.use(morgan(NODE_ENV === 'production' ? 'combined' : 'dev'));

/* ------------------------------- Routes ---------------------------- */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', validateUserQuery, (req, res, next) => {
  try {
    // In a real app you would pull from a DB using the validated limit/offset
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];
    res.json(users);
  } catch (err) {
    next(err); // forward to the global error handler
  }
});

/* -------------------------  404 fallback  -------------------------- */
app.use((_req, _res, next) => {
  const err = new Error('Not Found');
  err.statusCode = 404;
  next(err);
});

/* -----------------------  Central error handler  ------------------- */
app.use(errorHandler);

/* ---------------------------  Server start  ------------------------ */
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} (env=${NODE_ENV})`);
});

/* Graceful shutdown */
function shutdown(signal) {
  console.log(`\nReceived ${signal}. Closing server…`);
  server.close(() => {
    console.log('Server closed. Exiting process.');
    process.exit(0);
  });
}
process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));

/* Export for testing */
module.exports = app;
```

### What changed?

| Area | Before | After | Benefit |
|------|--------|-------|---------|
| **Headers** | None | `helmet()` | Mitigates XSS, click‑jacking, MIME‑sniffing, etc. |
| **Rate‑limit** | None | `express-rate-limit` | Stops brute‑force / DoS. |
| **CORS** | None | `cors()` with explicit origin | Prevents unwanted cross‑origin reads. |
| **Body parsing** | None | `express.json({ limit: '1mb' })` | Limits payload size, protects against memory‑exhaustion attacks. |
| **Logging** | `console.log` only on start | `morgan` (dev/combined) | Auditable request logs. |
| **Input validation** | N/A | `validateUserQuery` (Joi) | Guarantees type/range, returns 400 on bad data. |
| **Error handling** | No error middleware | Central `errorHandler` + 404 catcher | Consistent JSON errors, never leaks stack traces in prod. |
| **Config** | Hard‑coded port | `process.env.PORT` | Works on any environment, avoids leaving dev defaults in prod. |
| **Graceful shutdown** | None | Signal handlers for `SIGTERM`/`SIGINT` | Allows in‑flight requests to finish, avoids corrupted state. |

