 * It attempts to:
 *   • Connect to the PostgreSQL instance via `DATABASE_URL` and run a tiny query.
 *   • Call AWS STS `GetCallerIdentity` (the light‑weight way to prove the keys work).
 *   • Ping the Anthropic API (list models) using `ANTHROPIC_API_KEY`.
 *   • List a single Stripe charge using `STRIPE_SECRET_KEY`.
 *   • Send a HEAD request to a generic Logfire endpoint using `LOGFIRE_TOKEN`.
 *
 * The script prints a concise result for each credential and exits with
 *   code 0 if all checks succeeded, otherwise 1.
 *
 * NOTE: The canary values shipped with this repo are *intentionally invalid* –
 * the script will therefore report failures.  It is provided as a template
 * for when you replace the canary secrets with real ones.
 */

require('dotenv').config({ path: '.env.test' }); // Load the test env file

const { Client } = require('pg');
const AWS = require('aws-sdk');
const fetch = require('node-fetch');

async function checkPostgres() {
  const url = process.env.DATABASE_URL;
  if (!url) return { ok: false, error: 'DATABASE_URL not set' };
  const client = new Client({ connectionString: url, connectionTimeoutMillis: 5000 });
  try {
    await client.connect();
    const res = await client.query('SELECT 1');
    await client.end();
    return { ok: res.rowCount === 1 };
  } catch (err) {
    return { ok: false, error: err.message };
  }
}

async function checkAws() {
  const { AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY } = process.env;
  if (!AWS_ACCESS_KEY_ID || !AWS_SECRET_ACCESS_KEY) {
    return { ok: false, error: 'AWS credentials missing' };
  }
  const sts = new AWS.STS({
    accessKeyId: AWS_ACCESS_KEY_ID,
    secretAccessKey: AWS_SECRET_ACCESS_KEY,
    region: 'us-east-1',
    httpOptions: { timeout: 5000 },
  });
  try {
    await sts.getCallerIdentity({}).promise();
    return { ok: true };
  } catch (err) {
    return { ok: false, error: err.message };
  }
}

async function checkAnthropic() {
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) return { ok: false, error: 'ANTHROPIC_API_KEY not set' };
  try {
    const resp = await fetch('https://api.anthropic.com/v1/models', {
      headers: { 'x-api-key': apiKey },
      timeout: 5000,
    });
    if (!resp.ok) return { ok: false, error: `HTTP ${resp.status}` };
    return { ok: true };
  } catch (err) {
    return { ok: false, error: err.message };
  }
}

async function checkStripe() {
  const secret = process.env.STRIPE_SECRET_KEY;
  if (!secret) return { ok: false, error: 'STRIPE_SECRET_KEY not set' };
  try {
    const resp = await fetch('https://api.stripe.com/v1/charges?limit=1', {
      headers: { Authorization: `Bearer ${secret}` },
      timeout: 5000,
    });
    if (!resp.ok) return { ok: false, error: `HTTP ${resp.status}` };
    return { ok: true };
  } catch (err) {
    return { ok: false, error: err.message };
  }
}

async function checkLogfire() {
  const token = process.env.LOGFIRE_TOKEN;
  if (!token) return { ok: false, error: 'LOGFIRE_TOKEN not set' };
  // Logfire does not have a public health‑check endpoint, so we just hit the base URL.
  try {
    const resp = await fetch('https://logfire.io/api/ping', {
      method: 'HEAD',
      headers: { Authorization: `Bearer ${token}` },
      timeout: 5000,
    });
    if (!resp.ok) return { ok: false, error: `HTTP ${resp.status}` };
    return { ok: true };
  } catch (err) {
    return { ok: false, error: err.message };
  }
}

(async () => {
  const checks = {
    PostgreSQL: await checkPostgres(),
    AWS: await checkAws(),
    Anthropic: await checkAnthropic(),
    Stripe: await checkStripe(),
    Logfire: await checkLogfire(),
  };

  let allOk = true;
  console.log('Credential validation results:');
  for (const [name, result] of Object.entries(checks)) {
    if (result.ok) {
      console.log(`  ✅ ${name}: OK`);
    } else {
      allOk = false;
      console.log(`  ❌ ${name}: FAILED – ${result.error}`);
    }
  }

  process.exit(allOk ? 0 : 1);
})();

