## 6️⃣ Putting it all together – final `app.js` skeleton

```js
// ------------------------------------------------------------
//  app.js – secure starter for an Express API
// ------------------------------------------------------------
require('dotenv').config();               // Load .env (never commit the file)
const express   = require('express');
const helmet    = require('helmet');
const cors      = require('cors');
const rateLimit = require('express-rate-limit');
const xssClean  = require('xss-clean');
const { body, validationResult } = require('express-validator');

const app = express();

// ── 1️⃣ Security middle‑ware ─────────────────────────────────────
app.use(helmet());
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || [],
  methods: ['GET','POST','PUT','DELETE'],
  credentials: true,
}));
app.use(rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
}));
app.use(xssClean());
app.use(express.json({ limit: '10kb' }));

// ── 2️⃣ Async wrapper ───────────────────────────────────────────
const asyncHandler = fn => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ── 3️⃣ Validation helper ───────────────────────────────────────
const validate = checks => async (req, res, next) => {
  await Promise.all(checks.map(c => c.run(req)));
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: { message: 'Invalid request', details: errors.array() }
    });
  }
