// verify-creds.js
// ---------------------------------------------------------------
// Quick “smoke‑test” that each credential in .env.test is alive.
// ---------------------------------------------------------------
require('dotenv').config({ path: '.env.test' });

const { Client } = require('pg');                     // PostgreSQL
const AWS = require('aws-sdk');                       // AWS
const axios = require('axios');                       // Generic HTTP
const Stripe = require('stripe');                     // Stripe
const process = require('process');

// Helper to print results in a consistent way
function logResult(service, ok, details) {
  const status = ok ? '✅ SUCCESS' : '❌ FAILURE';
  console.log(`[${service}] ${status}${details ? ` – ${details}` : ''}`);
}

// ---------------------------------------------------------------
// 1️⃣ PostgreSQL (DATABASE_URL)
// ---------------------------------------------------------------
async function testPostgres() {
  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl) return logResult('PostgreSQL', false, 'DATABASE_URL not set');

  const client = new Client({ connectionString: dbUrl });
  try {
    await client.connect();
    const res = await client.query('SELECT 1 AS ok');
    if (res.rows[0]?.ok === 1) {
      logResult('PostgreSQL', true);
    } else {
      logResult('PostgreSQL', false, 'Unexpected query result');
    }
  } catch (err) {
    logResult('PostgreSQL', false, err.message);
  } finally {
    await client.end().catch(() => {}); // ignore close errors
  }
}

// ---------------------------------------------------------------
// 2️⃣ AWS (AWS_ACCESS_KEY_ID / AWS_SECRET_ACCESS_KEY)
// ---------------------------------------------------------------
async function testAws() {
  const { AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY } = process.env;
  if (!AWS_ACCESS_KEY_ID || !AWS_SECRET_ACCESS_KEY) {
    return logResult('AWS', false, 'Missing AWS credentials');
  }

  // Use STS GetCallerIdentity – a cheap, read‑only call
  const sts = new AWS.STS({ apiVersion: '2011-06-15' });
  try {
    const data = await sts.getCallerIdentity().promise();
    logResult('AWS', true, `ARN: ${data.Arn}`);
  } catch (err) {
    logResult('AWS', false, err.message);
  }
}

// ---------------------------------------------------------------
// 3️⃣ Anthropic (ANTHROPIC_API_KEY)
// ---------------------------------------------------------------
