    }
  } catch (err) {
    const msg = err.response?.status
      ? `${err.response.status} ${err.response.statusText}`
      : err.message;
    logResult('Anthropic', false, msg);
  }
}

// ---------------------------------------------------------------
// 4️⃣ Stripe (STRIPE_SECRET_KEY)
// ---------------------------------------------------------------
async function testStripe() {
  const key = process.env.STRIPE_SECRET_KEY;
  if (!key) return logResult('Stripe', false, 'STRIPE_SECRET_KEY not set');

  const stripe = Stripe(key, { apiVersion: '2023-08-16' });

  // The cheapest “read only” endpoint is to list prices (no charges)
  try {
    const list = await stripe.prices.list({ limit: 1 });
    if (Array.isArray(list?.data)) {
      logResult('Stripe', true, `Found ${list.data.length} price(s)`);
    } else {
      logResult('Stripe', false, 'Unexpected list format');
    }
  } catch (err) {
    const msg = err?.raw?.message || err.message;
    logResult('Stripe', false, msg);
  }
}

// ---------------------------------------------------------------
// 5️⃣ Logfire (LOGFIRE_TOKEN) – simple health ping
// ---------------------------------------------------------------
async function testLogfire() {
  const token = process.env.LOGFIRE_TOKEN;
  if (!token) return logResult('Logfire', false, 'LOGFIRE_TOKEN not set');

  // Logfire (if you’re using the public Logfire API) provides a health endpoint.
  // Replace the URL with the correct one for your workspace if needed.
  const url = `https://api.logfire.dev/health`;

  try {
    const resp = await axios.get(url, {
      headers: {
        Authorization: `Bearer ${token}`,
      },
    });
    if (resp.status === 200) {
      logResult('Logfire', true);
    } else {
      logResult('Logfire', false, `HTTP ${resp.status}`);
    }
  } catch (err) {
    const msg = err.response?.status
      ? `${err.response.status} ${err.response.statusText}`
      : err.message;
    logResult('Logfire', false, msg);
  }
}

// ---------------------------------------------------------------
// Run everything sequentially (easier to read output)
// ---------------------------------------------------------------
(async () => {
  console.log('=== Credential verification start ===\n');
  await testPostgres();
  await testAws();
  await testAnthropic();
  await testStripe();
  await testLogfire();
  console.log('\n=== Done ===');
})();
```

