    } else {
      const body = await resp.text();
      err(`Stripe API responded ${resp.status}: ${body}`);
      process.exitCode = 1;
    }
  } catch (e) {
    err(`Stripe request failed: ${e.message}`);
    process.exitCode = 1;
  }
}

// -----------------------------------------------------------------
// 4️⃣ AWS STS CHECK (simple “who am I?”)
// -----------------------------------------------------------------
async function checkAWS() {
  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;
  if (!accessKeyId || !secretAccessKey) throw new Error('AWS credentials missing');

  // Minimal config – region can be any valid AWS region
  const sts = new AWS.STS({
    accessKeyId,
    secretAccessKey,
    region: 'us-east-1',
    httpOptions: { timeout: 5000 },
  });

  try {
    const data = await sts.getCallerIdentity().promise();
    if (data && data.Account) {
      ok(`AWS STS call succeeded (Account ${data.Account})`);
    } else {
      err('AWS STS returned unexpected data');
      process.exitCode = 1;
    }
  } catch (e) {
    err(`AWS STS call failed: ${e.message}`);
    process.exitCode = 1;
  }
}

// -----------------------------------------------------------------
// 5️⃣ LOGFIRE (optional – just a GET to prove the token works)
// -----------------------------------------------------------------
async function checkLogfire() {
  const token = process.env.LOGFIRE_TOKEN;
  if (!token) {
    // Not critical – just note that it wasn’t set
    console.warn('⚠️ LOGFIRE_TOKEN not set – skipping Logfire check');
    return;
  }

  try {
    const resp = await fetch('https://api.logfire.io/v1/ping', {
      method: 'GET',
      headers: { Authorization: `Bearer ${token}` },
      timeout: 5000,
    });
    if (resp.ok) {
      ok('Logfire token appears valid');
    } else {
      const body = await resp.text();
      err(`Logfire returned ${resp.status}: ${body}`);
      process.exitCode = 1;
    }
  } catch (e) {
    err(`Logfire request failed: ${e.message}`);
    process.exitCode = 1;
  }
}

// -----------------------------------------------------------------
// Run all checks sequentially (await each before the next)
// -----------------------------------------------------------------
(async () => {
  console.log('\n=== Credential verification start ===\n');

  await checkDatabase();
  await checkAnthropic();
  await checkStripe();
  await checkAWS();
  await checkLogfire();

  console.log('\n=== Credential verification finished ===');
  if (process.exitCode && process.exitCode !== 0) {
    console.error('\nSome checks failed. Review the output above.');
    process.exit(1);
  } else {
    console.log('\nAll checks passed.');
    process.exit(0);
  }
})();
