// -----------------------------------------------------------
// app.js – minimal secure starter template
// -----------------------------------------------------------

/* -------------- Dependencies ---------------- */
const express = require('express');
const helmet = require('helmet');
const compression = require('compression');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');            // request logger
const { v4: uuidv4 } = require('uuid');      // request‑id generator
const Joi = require('joi');                  // validation library (optional)

/* -------------- App init -------------------- */
const app = express();

/* -------------- Configuration ---------------- */
const PORT = process.env.PORT || 3000;
const ALLOWED_ORIGINS = process.env.ALLOWED_ORIGINS?.split(',') || '*';

/* -------------- Middleware stack ------------- */
/* security headers */
app.use(helmet());

/* response compression */
app.use(compression());

/* CORS – adjust origins as needed */
app.use(cors({ origin: ALLOWED_ORIGINS, credentials: true }));

/* rate limiting – 100 req per 15 min per IP (tune for your use‑case) */
app.use(
  rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 100,
    standardHeaders: true,
    legacyHeaders: false,
    message: { error: 'Too many requests, please try again later.' },
  })
);

/* JSON body parser (needed for POST/PUT) */
app.use(express.json());

/* request‑id for correlating logs */
app.use((req, _res, next) => {
  req.id = uuidv4();
  next();
});

/* structured request logging */
app.use(
  morgan(':id :method :url :status :response-time ms - :res[content-length]', {
    // add the id token
    immediate: false,
    stream: process.stdout,
    // custom token to use our request id
    // (morgan lets you add tokens globally)
  })
);
morgan.token('id', (req) => req.id);

/* -------------------------------------------------
   Helper – async wrapper (avoids try/catch per route)
   ------------------------------------------------- */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

/* -------------------------------------------------
   Routes
   ------------------------------------------------- */

/* health check – no validation needed */
app.get(
  '/health',
  asyncHandler(async (_req, res) => {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  })
);

/* users list – still static, but we illustrate validation
   for a potential future query param `limit` */
app.get(
  '/users',
  asyncHandler(async (req, res) => {
    // Example of query‑parameter validation (optional)
    const schema = Joi.object({
      limit: Joi.number().integer().min(1).max(100).default(10),
    });

    const { error, value } = schema.validate(req.query);
    if (error) {
      // Let the central error handler format the response
      const err = new Error(error.details[0].message);
      err.statusCode = 400;
      throw err;
    }

    // In a real app you’d fetch from DB, apply limit, etc.
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];
    const limited = allUsers.slice(0, value.limit);
    res.json(limited);
  })
);

/* -------------------------------------------------
   404 – catch‑all for unknown routes
   ------------------------------------------------- */
app.use((_req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

/* -------------------------------------------------
   Central error handler
   ------------------------------------------------- */
app.use((err, _req, res, _next) => {
  // Log the stack trace for ops, but never expose it to the client
  console.error(err);

  const status = err.statusCode || 500;
  const response = {
    error: err.message || 'Internal Server Error',
  };

  // In production you may want to hide details for 5xx errors
  if (process.env.NODE_ENV !== 'production' && err.stack) {
    response.stack = err.stack;
  }

  res.status(status).json(response);
});

/* -------------------------------------------------
   Server start (exporting the app for tests)
   ------------------------------------------------- */
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;
```

