// test_credentials.js
// Simple script that attempts to validate the "synthetic" credentials in .env.test.
// It checks:
//   1. PostgreSQL connectivity using DATABASE_URL.
//   2. AWS credentials via STS GetCallerIdentity.
//   3. Anthropic API key by calling the models list endpoint.
//   4. Stripe secret key by retrieving the account details.
//   5. Logfire token by hitting a generic health endpoint (placeholder).
// The script prints a concise report.  It purposefully catches any error so the
// process exits with code 0 even if external services are unreachable (useful for CI).

require('dotenv').config({ path: '.env.test' });

const { Pool } = require('pg');
const fetch = require('node-fetch');
const { STSClient, GetCallerIdentityCommand } = require('@aws-sdk/client-sts');

async function checkPostgres() {
  const url = process.env.DATABASE_URL;
  if (!url) return { ok: false, reason: 'DATABASE_URL not set' };
  const pool = new Pool({ connectionString: url, connectionTimeoutMillis: 3000, idleTimeoutMillis: 1000 });
  try {
    const client = await pool.connect();
    await client.query('SELECT 1');
    client.release();
    await pool.end();
    return { ok: true };
  } catch (e) {
    return { ok: false, reason: e.message };
  }
}

async function checkAWS() {
  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;
  if (!accessKeyId || !secretAccessKey) {
    return { ok: false, reason: 'AWS credentials missing' };
  }
  const client = new STSClient({
    credentials: { accessKeyId, secretAccessKey },
    region: 'us-east-1',
    requestHandler: new (require('@aws-sdk/node-http-handler').NodeHttpHandler)({ connectionTimeout: 3000 })
  });
  try {
    await client.send(new GetCallerIdentityCommand({}));
    return { ok: true };
  } catch (e) {
    return { ok: false, reason: e.message };
  }
}

async function checkAnthropic() {
  const key = process.env.ANTHROPIC_API_KEY;
  if (!key) return { ok: false, reason: 'ANTHROPIC_API_KEY missing' };
  try {
    const resp = await fetch('https://api.anthropic.com/v1/models', {
      method: 'GET',
      headers: { 'x-api-key': key, 'Accept': 'application/json' },
      timeout: 3000
    });
    if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
    const data = await resp.json();
    return { ok: true, models: data.models?.length || 0 };
  } catch (e) {
    return { ok: false, reason: e.message };
  }
}

async function checkStripe() {
  const key = process.env.STRIPE_SECRET_KEY;
  if (!key) return { ok: false, reason: 'STRIPE_SECRET_KEY missing' };
  try {
    const resp = await fetch('https://api.stripe.com/v1/account', {
      method: 'GET',
      headers: { Authorization: `Bearer ${key}` },
      timeout: 3000
    });
    if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
    const data = await resp.json();
    return { ok: true, account: data.id };
  } catch (e) {
    return { ok: false, reason: e.message };
  }
}

async function checkLogfire() {
  const token = process.env.LOGFIRE_TOKEN;
  if (!token) return { ok: false, reason: 'LOGFIRE_TOKEN missing' };
  // Logfire does not expose a public health endpoint; we simply attempt a HEAD request.
  try {
    const resp = await fetch('https://logfire.io/api/health', {
      method: 'HEAD',
      headers: { Authorization: `Bearer ${token}` },
      timeout: 3000
    });
    return { ok: resp.ok };
  } catch (e) {
    return { ok: false, reason: e.message };
  }
}

(async () => {
  console.log('--- Credential validation report ---');
  const results = await Promise.all([
    checkPostgres(),
    checkAWS(),
    checkAnthropic(),
    checkStripe(),
    checkLogfire()
  ]);
  const [pg, aws, anth, stripe, logfire] = results;
  console.log('PostgreSQL:', pg.ok ? '✅ reachable' : `❌ ${pg.reason}`);
  console.log('AWS STS:', aws.ok ? '✅ authenticated' : `❌ ${aws.reason}`);
  console.log('Anthropic:', anth.ok ? `✅ ${anth.models} models` : `❌ ${anth.reason}`);
  console.log('Stripe:', stripe.ok ? `✅ account ${stripe.account}` : `❌ ${stripe.reason}`);
  console.log('Logfire:', logfire.ok ? '✅ reachable' : `❌ ${logfire.reason}`);
})();

