// -------------------------------------------------------------
// test-config.js – quick sanity‑check for all external secrets
// -------------------------------------------------------------
require('dotenv').config();               // loads .env.test (or .env) into process.env
const { Client } = require('pg');
const AWS = require('aws-sdk');
const Anthropic = require('@anthropic-ai/sdk');
const Stripe = require('stripe');
const Logfire = require('logfire-node');

// Helper to pretty‑print results
function ok(name)   { console.log(`✅ ${name}: ok`); }
function fail(name, err) {
  console.error(`❌ ${name}: FAILED`);
  console.error('   →', err && err.message ? err.message : err);
}

// -----------------------------------------------------------------
// 1️⃣ DATABASE_URL – try a simple SELECT 1
// -----------------------------------------------------------------
async function testDatabase() {
  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl) throw new Error('DATABASE_URL not set');

  const client = new Client({ connectionString: dbUrl });
  await client.connect();
  const res = await client.query('SELECT 1 as ok');
  await client.end();

  if (res.rows[0].ok !== 1) throw new Error('Unexpected query result');
}

(async () => {
  // ---------- DATABASE ----------
  try {
    await testDatabase();
    ok('DATABASE_URL');
  } catch (e) { fail('DATABASE_URL', e); }

  // ---------- AWS ----------
  try {
    const sts = new AWS.STS({
      accessKeyId: process.env.AWS_ACCESS_KEY_ID,
      secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
      // No region needed for STS GetCallerIdentity
    });
    const data = await sts.getCallerIdentity().promise();
    // If we get an ARN back, the keys are at least valid.
    if (!data.Arn) throw new Error('No ARN returned');
    ok('AWS credentials (STS GetCallerIdentity)');
  } catch (e) { fail('AWS credentials', e); }

  // ---------- Anthropic ----------
  try {
    const client = new Anthropic({
      apiKey: process.env.ANTHROPIC_API_KEY,
    });
    // A lightweight request – ask for a 1‑token completion.
    const resp = await client.completions.create({
      model: 'claude-3-sonnet-20240229', // any model works
      max_tokens: 1,
      prompt: '\n\nHuman: Hello\n\nAssistant:',
    });
    if (!resp || typeof resp.completion !== 'string')
      throw new Error('Invalid response shape');
    ok('Anthropic API key');
  } catch (e) { fail('Anthropic API key', e); }

  // ---------- Stripe ----------
  try {
    const stripe = Stripe(process.env.STRIPE_SECRET_KEY, {
      apiVersion: '2023-10-16',
    });
    // Retrieve your own account – works for both test and live keys.
    const acct = await stripe.accounts.retrieve();
    if (!acct || !acct.id) throw new Error('Unable to fetch account');
    ok('Stripe secret key');
  } catch (e) { fail('Stripe secret key', e); }

  // ---------- Logfire ----------
  try {
    const token = process.env.LOGFIRE_TOKEN;
    if (!token) throw new Error('LOGFIRE_TOKEN not set');

    const client = new Logfire({ token });
    // Send a tiny heartbeat event – it should resolve quickly.
    await client.event('test_heartbeat', { ts: new Date().toISOString() });
    ok('Logfire token');
  } catch (e) { fail('Logfire token', e); }

  console.log('\n=== DONE ===');
})();
```

### How the script works

| Service | What we call | Why this is safe |
|---------|--------------|-------------------|
| **PostgreSQL** (`pg`) | `SELECT 1` | No data is written, just a read‑only health check. |
| **AWS** (`STS#getCallerIdentity`) | Returns the AWS account ARN for the supplied keys. | No charges, no side effects. |
| **Anthropic** | Minimal `completions.create` with 1 token. | Very cheap (few‑cent usage) and read‑only. |
| **Stripe** | `stripe.accounts.retrieve()` | Only reads account metadata. Works with both test and live keys. |
| **Logfire** | Sends a single `test_heartbeat` event. | A single non‑blocking log entry. |

If any of the calls fails (network error, authentication error, expired key, etc.) the script will print a clear `❌` line with the error message.

