## 2. `verify-credentials.js`

```js
#!/usr/bin/env node
/**
 * verify-credentials.js
 *
 * Quick health‑check for the secrets defined in .env.test.
 * -------------------------------------------------------
 *  • Connects to DATABASE_URL and runs SELECT 1.
 *  • Calls a minimal endpoint of each third‑party API.
 *  • Prints a concise PASS/FAIL report – no secret values are echoed.
 *
 *  Usage:
 *      node verify-credentials.js               # defaults to .env.test
 *      NODE_ENV=production node verify-credentials.js   # loads .env
 *
 *  Exit code: 0 = all OK, 1 = at least one failure.
 */

const fs = require('fs');
const path = require('path');
const { Client } = require('pg');
const axios = require('axios');
require('dotenv').config({ path: path.resolve(process.env.NODE_ENV === 'production' ? '.env' : '.env.test') });

/**
 * Helper – prints a line with a ✅ or ❌ emoji.
 */
function report(name, ok, extra = '') {
  const status = ok ? '✅ PASS' : '❌ FAIL';
  console.log(`${status} – ${name}${extra ? ` (${extra})` : ''}`);
}

/**
 * 1️⃣ Verify DATABASE_URL
 */
async function checkDatabase() {
  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl) {
    report('DATABASE_URL', false, 'not set');
    return false;
  }

  const client = new Client({ connectionString: dbUrl, connectionTimeoutMillis: 5000 });
  try {
    await client.connect();
    const res = await client.query('SELECT 1');
    if (res && res.rowCount === 1) {
      report('DATABASE_URL (SELECT 1)', true);
      return true;
    }
    report('DATABASE_URL (SELECT 1)', false, 'unexpected result');
    return false;
  } catch (err) {
    report('DATABASE_URL (connect/query)', false, err.message);
    return false;
  } finally {
    await client.end().catch(() => {});
  }
}

/**
 * 2️⃣ Verify Anthropic API key – we use the public "models/list" endpoint.
 */
async function checkAnthropic() {
  const key = process.env.ANTHROPIC_API_KEY;
  if (!key) {
    report('ANTHROPIC_API_KEY', false, 'not set');
    return false;
  }

  try {
    const resp = await axios.post(
      'https://api.anthropic.com/v1/complete',
      // Minimal payload – the endpoint will reject an empty prompt, but it’ll still return 200 auth‑wise.
      { prompt: '\n\nHuman:', max_tokens_to_sample: 1, model: 'claude-2.0' },
      {
        headers: {
          'x-api-key': key,
          'anthropic-version': '2023-06-01',
          'content-type': 'application/json',
        },
        timeout: 7000,
      }
    );
    // If we got *any* 2xx response, the key is accepted.
    report('ANTHROPIC_API_KEY', resp.status >= 200 && resp.status < 300);
    return resp.status >= 200 && resp.status < 300;
  } catch (err) {
    const msg = err.response ? `${err.response.status}` : err.message;
    report('ANTHROPIC_API_KEY', false, msg);
    return false;
  }
}

/**
 * 3️⃣ Verify Stripe secret key – use the “retrieve account” endpoint.
 */
async function checkStripe() {
  const key = process.env.STRIPE_SECRET_KEY;
  if (!key) {
    report('STRIPE_SECRET_KEY', false, 'not set');
    return false;
  }

  try {
    const resp = await axios.get('https://api.stripe.com/v1/account', {
      auth: { username: key, password: '' },
      timeout: 7000,
    });
    report('STRIPE_SECRET_KEY', resp.status === 200);
    return resp.status === 200;
  } catch (err) {
    const msg = err.response ? `${err.response.status}` : err.message;
    report('STRIPE_SECRET_KEY', false, msg);
    return false;
  }
}

/**
 * 4️⃣ Verify Logfire token – Logfire offers a simple “ping” endpoint.
 *    (If you use a different provider, replace the URL accordingly.)
 */
async function checkLogfire() {
  const token = process.env.LOGFIRE_TOKEN;
  if (!token) {
    report('LOGFIRE_TOKEN', false, 'not set');
    return false;
  }

  try {
    const resp = await axios.get('https://logfire-api.com/v1/ping', {
      headers: { Authorization: `Bearer ${token}` },
      timeout: 5000,
    });
    // Assume a 200 means the token is recognised.
    report('LOGFIRE_TOKEN', resp.status === 200);
    return resp.status === 200;
  } catch (err) {
    const msg = err.response ? `${err.response.status}` : err.message;
    // Some services return 401 for an *invalid* token; treat that as a clear FAIL.
    report('LOGFIRE_TOKEN', false, msg);
    return false;
  }
}

/**
 * 5️⃣ Verify AWS credentials – call STS GetCallerIdentity (requires
 *    the `aws-sdk` package).  If you don’t want to install it, you can
 *    skip this step.
 */
async function checkAws() {
  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;
  if (!accessKeyId || !secretAccessKey) {
    report('AWS credentials', false, 'missing key/secret');
    return false;
  }

  // Lazy‑load to avoid pulling in the SDK if the user never calls this script.
  const { STSClient, GetCallerIdentityCommand } = require('@aws-sdk/client-sts');

  const client = new STSClient({
    credentials: { accessKeyId, secretAccessKey },
    region: 'us-east-1', // region is irrelevant for STS GetCallerIdentity
  });

  try {
    await client.send(new GetCallerIdentityCommand({}));
    report('AWS credentials (STS GetCallerIdentity)', true);
    return true;
  } catch (err) {
    const msg = err.name ? `${err.name}: ${err.message}` : err.message;
    report('AWS credentials (STS GetCallerIdentity)', false, msg);
    return false;
  }
}

/**
 * Run all checks sequentially and exit with a proper code.
 */
(async () => {
  const results = await Promise.all([
    checkDatabase(),
    checkAnthropic(),
    checkStripe(),
    checkLogfire(),
    checkAws(),
  ]);

  const allOk = results.every(Boolean);
  console.log('\nSummary:', allOk ? '✅ All credentials verified' : '❌ Some checks failed');

  process.exit(allOk ? 0 : 1);
})();
```

