// app.js
'use strict';

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { body, query, validationResult } = require('express-validator');

const app = express();

// ---------- Middleware ----------
app.use(helmet());                         // Secure headers
app.use(cors({ origin: process.env.ALLOWED_ORIGIN || '*' })); // Adjust for your domain
app.use(express.json());                  // Parse JSON payloads
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// Rate limiting – 100 req / 15 min per IP (tweak as needed)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// ---------- Routes ----------
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
  });
});

/**
 * In a real product you would protect this endpoint (e.g., JWT, OAuth2)
 * and never leak raw email addresses unless the caller is authorised.
 */
app.get(
  '/users',
  // Example of input validation – suppose you support a `?limit=` query param
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .toInt()
    .withMessage('limit must be an integer between 1 and 100'),
  (req, res, next) => {
    // Validate query parameters
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      // 400 – Bad request with detailed validation errors
      return res.status(400).json({ errors: errors.array() });
    }

    // Simulate data fetch – wrap in try/catch or use async/await with .catch(next)
    try {
      const limit = req.query.limit || 2;
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ].slice(0, limit);

      // If you ever expose PII, consider stripping it for unauthenticated callers.
      res.json(users);
    } catch (err) {
      next(err); // Forward to error‑handling middleware
    }
  }
);

// ---------- Error handling ----------
/**
 * Central error handler – ensures we never leak stack traces in prod.
 * It also guarantees a JSON response for consistency.
 */
app.use((err, req, res, next) => {
  // Log the error (you can replace with winston / pino)
  console.error(err);

  const status = err.status || 500;
  const response = {
    error:
      process.env.NODE_ENV === 'production'
        ? 'Internal server error'
        : err.message,
  };

  // Include stack only in non‑production for debugging
  if (process.env.NODE_ENV !== 'production') {
    response.stack = err.stack;
  }

  res.status(status).json(response);
});

// ---------- Server start ----------
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

/* Graceful shutdown – useful for Docker/K8s */
function shutdown() {
  console.log('Gracefully shutting down...');
  server.close(() => {
    console.log('Closed out remaining connections');
    process.exit(0);
  });

  // Force shutdown after 10 secs
  setTimeout(() => {
    console.error('Forcing shutdown...');
    process.exit(1);
  }, 10_000);
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

module.exports = app;
```

