async function testPostgres() {
  const url = process.env.DATABASE_URL;
  if (!url) return report('Postgres', false, 'DATABASE_URL not set');

  const client = new Client({ connectionString: url });
  try {
    await client.connect();
    // A cheap query that succeeds on any DB
    const res = await client.query('SELECT 1 AS ok');
    if (res.rows[0].ok === 1) {
      report('Postgres', true, 'Connection succeeded');
    } else {
      report('Postgres', false, 'Unexpected query result');
    }
  } catch (err) {
    report('Postgres', false, err.message);
  } finally {
    await client.end().catch(() => {});
  }
}

