/**
 * Disaster‑Recovery backup script
 *
 * Reads the credentials that are already present in the environment
 * (e.g. from .env.test) and sends them as a JSON object to the local
 * backup collector at http://localhost:3003/api/dr-backup .
 *
 * Usage:
 *   $ node dr-backup.js          # reads from current process.env
 *   $ ENV_FILE=.env.test node dr-backup.js   # load a specific .env file first
 *
 * The script deliberately does not log the secret values – it only logs
 * success / failure of the HTTP request.
 */

const fs = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// 1️⃣ Load an optional .env file (mirrors the behaviour of `dotenv`)
// ---------------------------------------------------------------------------
function loadEnvFile(filePath) {
  const absolute = path.resolve(filePath);
  if (!fs.existsSync(absolute)) return;
  const lines = fs.readFileSync(absolute, 'utf8').split('\n');
  for (const line of lines) {
    // skip comments / empty lines
    if (!line.trim() || line.trim().startsWith('#')) continue;
    const [key, ...rest] = line.split('=');
    const value = rest.join('=').trim();
    if (!process.env[key]) {
      process.env[key] = value;
    }
  }
}

// If you run the script with a custom env file, set the ENV_FILE variable:
//   ENV_FILE=.env.test node dr-backup.js
if (process.env.ENV_FILE) {
  loadEnvFile(process.env.ENV_FILE);
}

// ---------------------------------------------------------------------------
// 2️⃣ Assemble the data we want to back up
// ---------------------------------------------------------------------------
const payload = {
  DATABASE_URL: process.env.DATABASE_URL,
  AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
  AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
  ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
  STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
  LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN,
};

// Optional sanity‑check: only send if at least one field is present
if (Object.values(payload).every((v) => v == null)) {
  console.error('❌ No credential data found in the environment – aborting.');
  process.exit(1);
}

// ---------------------------------------------------------------------------
// 3️⃣ POST to the local DR endpoint
// ---------------------------------------------------------------------------
const DR_ENDPOINT = 'http://localhost:3003/api/dr-backup';

(async () => {
  try {
    const response = await fetch(DR_ENDPOINT, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        // If the backup service expects an auth header you can add it here
        // 'Authorization': `Bearer ${process.env.SOME_BACKUP_TOKEN}`,
      },
      body: JSON.stringify(payload),
    });

    if (!response.ok) {
      const text = await response.text();
      console.error(
        `❌ Backup request failed – HTTP ${response.status} ${response.statusText}`
      );
      console.error('Response body:', text);
      process.exit(1);
    }

    console.log('✅ Backup succeeded.');
  } catch (err) {
    console.error('❌ Unexpected error while sending backup:', err);
    process.exit(1);
  }
})();
```

### How to run it

1. **Make sure the backup collector is listening** on `http://localhost:3003/api/dr-backup`.  
   (If it requires authentication, add the appropriate header in the script.)

2. **Load your environment file** (the script can do it for you).  
   ```bash
   ENV_FILE=.env.test node dr-backup.js
   ```

   – or, if you already have the variables exported in the shell, simply:

   ```bash
   node dr-backup.js
   ```

3. You should see either:

   * `✅ Backup succeeded.` – meaning the POST returned a 2xx status, **or**
   * an error message with the HTTP status / response body for troubleshooting.

---

### What the script does (and what it purposely avoids)

| ✅ Done | ❌ Not done (on purpose) |
|--------|--------------------------|
| Reads the values from `process.env` (or a supplied `.env` file). | Prints the actual secret values to the console (avoid accidental leaks). |
| Sends a **single JSON object** with all required keys. | Stores any copy of the credentials locally beyond the short‑lived in‑memory payload. |
| Returns a clear success/failure exit code (`0` on success, `1` on error). | Performs retries or exponential back‑off – you can add that if the backup service is flaky. |

Feel free to adapt the script (e.g., add more fields, change the endpoint URL, inject a bearer token) to match the exact contract your on‑call team expects.

