const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const hpp = require('hpp');
const xss = require('xss-clean');               // sanitises req.body, req.query, req.params
const { celebrate, Joi, errors, Segments } = require('celebrate'); // validation
const asyncHandler = fn => (req, res, next) => Promise.resolve(fn(req, res, next)).catch(next);

const app = express();

// ---------------------------------------------------------------------------
// Global middleware
// ---------------------------------------------------------------------------
app.use(helmet());                              // security headers
app.use(cors({                                 // restrict origins in production
  origin: process.env.CORS_ORIGIN || '*',
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
}));
app.use(hpp());                                 // protect against HTTP Parameter Pollution
app.use(xss());                                 // basic XSS sanitisation
app.use(express.json({ limit: '10kb' }));       // body parser + size limit

// Rate limiting – apply to all routes (adjust per endpoint if needed)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
