```js
#!/usr/bin/env node
/**
 * Simple sanity‑check for the credentials found in .env.test.
 *
 *   • PostgreSQL – open a connection and run SELECT 1
 *   • AWS       – call STS GetCallerIdentity (no permissions needed beyond valid keys)
 *   • Anthropic – request the /v1/models endpoint (public, cheap)
 *   • Stripe    – retrieve your account (requires a valid secret key)
 *   • Logfire   – ping the health endpoint (if any – we just do a GET)
 *
 * The script prints a one‑line “OK”/“FAIL” per service and exits with
 * code 0 if **all** checks succeed, otherwise 1.
 *
 * ---------------------------------------------------------------
 *   Do NOT commit this script (it contains secrets at runtime!)
 *   Keep it out of production bundles – it is for temporary testing.
 * ---------------------------------------------------------------
 */

const fs = require('fs');
const path = require('path');
require('dotenv').config({ path: path.resolve(__dirname, '.env.test') });

async function checkPostgres() {
  const { Client } = require('pg');
  const client = new Client({ connectionString: process.env.DATABASE_URL });

  try {
    await client.connect();
    const res = await client.query('SELECT 1');
    if (res.rowCount === 1) return true;
    return false;
  } catch (e) {
    return false;
  } finally {
    await client.end().catch(() => {});
  }
}

async function checkAWS() {
  const { STSClient, GetCallerIdentityCommand } = require('@aws-sdk/client-sts');
  const client = new STSClient({
    region: process.env.AWS_REGION || 'us-east-1',
    credentials: {
      accessKeyId: process.env.AWS_ACCESS_KEY_ID,
      secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
    },
  });

  try {
    await client.send(new GetCallerIdentityCommand({}));
    return true;
  } catch (e) {
    return false;
  }
}

async function checkAnthropic() {
  const fetch = require('node-fetch');
  const url = 'https://api.anthropic.com/v1/models';

  try {
    const resp = await fetch(url, {
      headers: {
        'x-api-key': process.env.ANTHROPIC_API_KEY,
        'anthropic-version': '2023-06-01',
      },
    });
    return resp.ok;
  } catch (e) {
    return false;
  }
}

async function checkStripe() {
  const Stripe = require('stripe');
  const stripe = Stripe(process.env.STRIPE_SECRET_KEY, { apiVersion: '2023-10-16' });

  try {
    const acct = await stripe.accounts.retrieve();
    return !!acct.id;
  } catch (e) {
    return false;
  }
}

async function checkLogfire() {
  // Logfire does not have a public health endpoint, but we can try a simple
  // GET to its API base with the token as a bearer auth header.
  const fetch = require('node-fetch');
  const url = 'https://api.logfire.dev/health'; // replace with real endpoint if known

  try {
    const resp = await fetch(url, {
      headers: {
        Authorization: `Bearer ${process.env.LOGFIRE_TOKEN}`,
      },
    });
    // Many services return 200 on health checks; we treat any 2xx as success.
    return resp.ok;
  } catch (e) {
    // If the endpoint doesn't exist, treat it as a “cannot verify” case.
    return false;
  }
}

/* ----------------------------------------------------------- */

async function main() {
  const checks = [
    { name: 'PostgreSQL', fn: checkPostgres },
    { name: 'AWS (STS)', fn: checkAWS },
    { name: 'Anthropic', fn: checkAnthropic },
    { name: 'Stripe', fn: checkStripe },
    { name: 'Logfire', fn: checkLogfire },
  ];

  let allOk = true;

  for (const { name, fn } of checks) {
    const ok = await fn();
    console.log(`${name}: ${ok ? '✅ OK' : '❌ FAIL'}`);
    if (!ok) allOk = false;
  }

  process.exit(allOk ? 0 : 1);
}

/* ----------------------------------------------------------- */

main().catch(err => {
  console.error('Unexpected error while verifying credentials:', err);
  process.exit(1);
});
```

### How to run it

1. **Install the required packages** (once):

   ```bash
   npm install pg @aws-sdk/client-sts node-fetch stripe dotenv
   ```

2. **Make the script executable** (optional):

   ```bash
   chmod +x verify-creds.js
   ```

3. **Execute**:

   ```bash
   node verify-creds.js
   # or, if made executable:
   ./verify-creds.js
   ```

   You’ll see output similar to:

   ```
   PostgreSQL: ✅ OK
   AWS (STS): ❌ FAIL
   Anthropic: ✅ OK
   Stripe: ❌ FAIL
   Logfire: ❌ FAIL
   ```

   The exit code (`0` = all good, `1` = at least one failed) makes it easy to integrate into CI pipelines.

### Things to keep in mind

| Service | What “OK” means | Why a failure may not mean “stale” |
|---------|----------------|-----------------------------------|
| PostgreSQL | Connection succeeded and `SELECT 1` ran. | Could be blocked by network firewalls or the DB is in maintenance mode. |
| AWS (STS) | The STS call returned a 200 and a caller identity. | Even with valid keys, the account may lack `sts:GetCallerIdentity` permission. |
| Anthropic | HTTP 2xx from `/v1/models`. | The key might be limited to a different region or API version. |
| Stripe | Account object returned (has an `id`). | Some secret keys are restricted to test mode only; you must hit the correct endpoint. |
| Logfire | Any 2xx response from the health endpoint (or a known API). | The service may not expose a health endpoint; consider swapping with a real API call if you have one. |

---

### Next steps (if you discover stale credentials)

1. **Rotate** the keys in the services that report a failure.  
2. Update `.env.test` (or whatever env‑file you use in production).  
3. Re‑run the script to confirm the new values work.  

Feel free to tweak the individual `check*` functions to suit the exact API versions or endpoints you prefer. The script is deliberately lightweight and safe for repeated execution. Happy testing!

