  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get(
  '/users',
  // ---- validation chain (optional paging) ----
  [
    query('page')
      .optional()
      .isInt({ min: 1 })
      .toInt(),
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .toInt(),
  ],
  asyncHandler(async (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
